        item.update(type="symlink", target=os.readlink(path))
    elif path.is_file():
        with path.open("rb") as stream:
            digest = hashlib.file_digest(stream, "sha256").hexdigest()
        item.update(type="file", size=path.stat().st_size, sha256=digest)
