import hashlib, json, tarfile; from pathlib import Path
store = Path("<store>")
source_path = store / "logs/sti-108-component-logs-source-hashes.log"
source = json.loads(source_path.read_text())
expected = {item["path"]: item for item in source["members"]}
archive = store / "artifacts/20261117-sti108-baseline/libwebsockets-task-logs.tar"
seen = set()
with tarfile.open(archive, "r:") as stream:
    for member in stream:
        if member.isdir():
            continue
        if not member.name.startswith(source["archive_prefix"]):
            raise RuntimeError("Unexpected archive prefix: " + member.name)
        name = member.name[len(source["archive_prefix"]):]
        if name in seen or name not in expected:
            raise RuntimeError("Unexpected or duplicate member: " + name)
        seen.add(name)
        item = expected[name]
        if item["type"] == "file":
            if not member.isfile() or member.size != item["size"]:
                raise RuntimeError("Incorrect file type/size: " + name)
            with stream.extractfile(member) as data:
                if hashlib.file_digest(data, "sha256").hexdigest() != item["sha256"]:
                    raise RuntimeError("Incorrect file bytes: " + name)
        elif item["type"] == "symlink":
            if not member.issym() or member.linkname != item["target"]:
                raise RuntimeError("Incorrect link target: " + name)
        else:
            raise RuntimeError("Unexpected source member type: " + name)
if seen != set(expected):
    raise RuntimeError("Incomplete component task-log handoff")
with archive.open("rb") as data:
    sha = hashlib.file_digest(data, "sha256").hexdigest()
result = {"status": "verified", "archive": "local://firmdura-kirkstone/artifacts/20261117-sti108-baseline/libwebsockets-task-logs.tar", "archive_size": archive.stat().st_size, "archive_sha256": sha, "source_index_sha256": hashlib.sha256(source_path.read_bytes()).hexdigest(), "regular_files": sum(item["type"] == "file" for item in expected.values()), "symlinks": sum(item["type"] == "symlink" for item in expected.values()), "logical_file_bytes": sum(item["size"] for item in expected.values() if item["type"] == "file")}
with (store / "runs/sti-108-component-logs-integrity.json").open("x") as output:
    json.dump(result, output, indent=2)
    output.write("\n")
print(json.dumps(result, indent=2))
